BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
LOCK TABLE tam_the_lookup_entries, calculation_rules, source_sections, source_books IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE year_import(key text PRIMARY KEY,element text,title text,note text) ON COMMIT DROP;
DO $$ BEGIN
IF (SELECT count(*) FROM calculation_rules r JOIN source_sections s ON s.id=r.source_section_id
 JOIN source_books b ON b.id=s.source_book_id
 WHERE r.module='TAM_THE' AND r.rule_code='TT-NGU-HANH' AND r.rule_version='1.0'
 AND b.id=(SELECT id FROM source_books WHERE title='Diễn Cầm Tam Thế Diễn Nghĩa' AND edition='Bản PDF scan người dùng cung cấp; chưa xác minh ấn bản in') AND b.file_sha256='7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d' AND b.pdf_page_count=360
 AND s.section_label='TT-NGU-HANH' AND s.pdf_page=11 AND s.printed_page_label='12'
 AND ((r.verification_status='SOURCE_LOCATED' AND r.reviewer IS NULL AND r.reviewed_at IS NULL
       AND r.verification_note IS NULL)
  OR (r.verification_status='VERIFIED' AND r.reviewer='Codex source review 2026-10-24 (same-tool second pass)' AND r.reviewed_at IS NOT NULL
      AND r.verification_note='S02 visual two-pass review of all 30 pairs/60 mappings in provided Tam The PDF11, print12; SHA256=7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d. Scope: normalized stem/branch codes and printed element column only. Descriptors/nap-am names are excluded; row28 prints HOA beside a tree descriptor (source anomaly). Meo normalized to MAO, Ty/with-dot to TI, Nh am spelling to NHAM by cycle position. Same AI tool at both passes, not an independent human TV2 confirmation; printed edition identity unverified. Reviewed 2026-10-24; reviewed_at is DB application time. See data/tam_the_year_element_review.csv and docs/22-S02-TAM-THE-YEAR-ELEMENTS.md.' AND r.description='Tra hành mệnh theo 60 Can Chi năm âm; cột mạng Số 4, PDF 11/trang in 12. Phạm vi duyệt không gồm mô tả nạp âm hoặc chuyển lịch.'))) <> 1
 THEN RAISE EXCEPTION 'Missing/changed/protected TT-NGU-HANH source or reviewer'; END IF;
IF EXISTS (SELECT 1 FROM tam_the_lookup_entries e JOIN calculation_rules r ON r.id=e.rule_id
 LEFT JOIN year_import n ON n.key=e.lookup_key
 WHERE r.module='TAM_THE' AND r.rule_code='TT-NGU-HANH' AND r.rule_version='1.0'
 AND (n.key IS NULL OR e.result_code<>n.element OR e.title<>n.title OR e.description IS NOT NULL
      OR e.source_section_id<>r.source_section_id OR e.editor IS DISTINCT FROM 'TV3_AI_ASSISTED_SOURCE_TRANSCRIPTION_2026_10_24'
      OR NOT ((e.verification_status='SOURCE_LOCATED' AND e.reviewer IS NULL
               AND e.reviewed_at IS NULL AND e.verification_note IS NULL)
           OR (e.verification_status='VERIFIED' AND e.reviewer='Codex source review 2026-10-24 (same-tool second pass)'
               AND e.reviewed_at IS NOT NULL AND e.verification_note=n.note))))
 THEN RAISE EXCEPTION 'Changed/protected year mapping: no overwrite or automatic re-approval'; END IF;
END $$;
DO $$ BEGIN
IF (SELECT count(*) FROM tam_the_lookup_entries e JOIN calculation_rules r ON r.id=e.rule_id
 WHERE r.module='TAM_THE' AND r.rule_code='TT-NGU-HANH' AND r.rule_version='1.0') <> 60
 THEN RAISE EXCEPTION 'Expected exactly 60 imported year mappings before review'; END IF;
END $$;
UPDATE tam_the_lookup_entries e SET verification_status='VERIFIED',
 reviewer='Codex source review 2026-10-24 (same-tool second pass)',reviewed_at=CURRENT_TIMESTAMP,verification_note=n.note
 FROM year_import n,calculation_rules r
 WHERE e.rule_id=r.id AND e.lookup_key=n.key AND r.module='TAM_THE'
 AND r.rule_code='TT-NGU-HANH' AND r.rule_version='1.0' AND e.verification_status='SOURCE_LOCATED';
UPDATE calculation_rules SET verification_status='VERIFIED',reviewer='Codex source review 2026-10-24 (same-tool second pass)',
 reviewed_at=CURRENT_TIMESTAMP,verification_note='S02 visual two-pass review of all 30 pairs/60 mappings in provided Tam The PDF11, print12; SHA256=7976f690145cc0bbdf6cb1bf2a0276b843512d231dca9a9f83b6f99820816c7d. Scope: normalized stem/branch codes and printed element column only. Descriptors/nap-am names are excluded; row28 prints HOA beside a tree descriptor (source anomaly). Meo normalized to MAO, Ty/with-dot to TI, Nh am spelling to NHAM by cycle position. Same AI tool at both passes, not an independent human TV2 confirmation; printed edition identity unverified. Reviewed 2026-10-24; reviewed_at is DB application time. See data/tam_the_year_element_review.csv and docs/22-S02-TAM-THE-YEAR-ELEMENTS.md.',description='Tra hành mệnh theo 60 Can Chi năm âm; cột mạng Số 4, PDF 11/trang in 12. Phạm vi duyệt không gồm mô tả nạp âm hoặc chuyển lịch.'
 WHERE module='TAM_THE' AND rule_code='TT-NGU-HANH' AND rule_version='1.0'
 AND verification_status='SOURCE_LOCATED';
COMMIT;
